INSERT INTO @T_Attachments( OldAttachmentId, OldAttachmentInst, PurposeCode, AttachmentId, AttachmentInstance ) SELECT , NewID(), 0 FROM
;
/* Update T_Attachments to add the old Physical File Name. Implemented via an update query in a desire not to risk breaking dynamic column names. */
UPDATE @T_Attachments SET OldPhysicalFileName= sourceMainTable.PhysicalFileName FROM @T_Attachments cachedColumns INNER JOIN DM_Attachment sourceMainTable ON cachedColumns.OldAttachmentId=sourceMainTable.attachmentId /* PFM-2136 : Add back attachment instance conjunction */ AND cachedColumns.OldAttachmentInst = sourceMainTable.AttachmentInstance; /* Insert into the Target Main Attachment Table */
INSERT INTO DM_Attachment(AttachmentId, FileLocation, FileName, FileExtension, AttachmentInstance, FileSize, UploadedDateTime, PhysicalFileName, FileDescription, CreatorId, CreatedDate, LastUpdateDate, LastUpdateId) SELECT mappings.AttachmentId, source.FileLocation, source.FileName, source.FileExtension, mappings.AttachmentInstance, source.FileSize, source.UploadedDateTime, mappings.AttachmentId + '_V0.' + source.FileExtension AS PhysicalFileName, source.FileDescription, , getdate(), getdate(),
FROM DM_Attachment source INNER JOIN @T_Attachments mappings ON source.AttachmentId=mappings.OldAttachmentId AND source.AttachmentInstance=mappings.OldAttachmentInst
/* Insert into the Target Wrapper Table */
