/* Former Conditional Update Part 1 */ UPDATE @T_Attachments SET OldFileLocation = DM.FileLocation + case right(DM.FileLocation,1) when '\' then '' else '\' end, NewPhysicalFileName = DM.PhysicalFileName FROM DM_Attachment DM JOIN @T_Attachments T ON T.AttachmentId = DM.AttachmentId AND T.AttachmentInstance = DM.AttachmentInstance;
/* Former Conditional Update Part 2 */ UPDATE DM_Attachment
FROM DM_Attachment DM JOIN @T_Attachments T ON T.AttachmentId = DM.AttachmentId AND T.AttachmentInstance = DM.AttachmentInstance;
/* Select the result set */ SELECT OldFileLocation, OldPhysicalFileName, NewPhysicalFileName, OldAttachmentId, AttachmentId AS NewAttachmentId FROM @T_Attachments

